fn frame(t: i32) {
    host::display::clear(0x0a0a0e);
    host::display::draw_string(8, 8, "DRAG THE TITLE BAR", 0xffffff, 1);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_module("clock", 140, 160, 200, 150));
        host::display::state_set(2, 140);
        host::display::state_set(3, 160);
    }
    let h: i32 = host::display::state_get(1);
    let mut wx: i32 = host::display::state_get(2);
    let mut wy: i32 = host::display::state_get(3);
    let mut drag: i32 = host::display::state_get(4);
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    if down == 1 {
        if drag == 0 && px >= wx && px < wx + 200 && py >= wy - 18 && py < wy {
            drag = 1;
        }
        if drag == 1 {
            wx = px - 100;
            wy = py + 18;
            if wx < 0 { wx = 0; }
            if wx > 312 { wx = 312; }
            if wy < 18 { wy = 18; }
            if wy > 362 { wy = 362; }
            host::compose::move_module(h, wx, wy, 200, 150);
        }
    } else {
        drag = 0;
    }
    host::display::state_set(2, wx);
    host::display::state_set(3, wy);
    host::display::state_set(4, drag);
    host::display::fill_rect(wx, wy - 18, 200, 18, 0x3050a0);
    host::display::draw_string(wx + 6, wy - 14, "CLOCK", 0xffffff, 1);
    let st: i32 = host::compose::status(h);
    if st == 0 { host::display::draw_string(wx + 8, wy + 60, "LOADING", 0xffff00, 1); }
    if st == 2 { host::display::draw_string(wx + 8, wy + 60, "FAILED", 0xff0000, 1); }
    host::display::present();
}
